import { ElementRef, Injectable, inject } from '@angular/core';
import { Observable } from 'rxjs';
import { TranslateService } from '@ngx-translate/core';

import { BookingsApiService } from '../../api/bookings-api.service';
import { ModalService } from '../../../shared/modal/modal.service';
import { i18nKey } from '../../../shared/i18n/i18n-key';

@Injectable({ providedIn: 'root' })
export class ChangeRequestModalService {
  private readonly modalService = inject(ModalService);
  private readonly translate = inject(TranslateService);
  private readonly bookingsApi = inject(BookingsApiService);

  openWithdraw(elementRef: ElementRef, bookingNumber: string, id: string): Observable<unknown> {
    return this.modalService.openConfirm(
      {
        title: this.instant(i18nKey('bookings.changeRequest.withdraw.title')),
        text: this.instant(i18nKey('bookings.changeRequest.withdraw.text')),
        okLabel: this.instant(i18nKey('bookings.changeRequest.withdraw.confirm')),
        cancelLabel: this.instant(i18nKey('bookings.modal.close')),
        onConfirm: () => this.bookingsApi.withdrawChangeRequest(bookingNumber, id),
        errorMessage: this.instant(i18nKey('bookings.changeRequest.withdraw.toast.failure')),
      },
      elementRef,
    ).modalRef.closed;
  }

  openAlreadyRequested(elementRef: ElementRef, bookingNumber: string, id: string): Observable<unknown> {
    return this.modalService.openConfirm(
      {
        title: this.instant(i18nKey('bookings.changeRequest.alreadyRequested.title')),
        text: this.instant(i18nKey('bookings.changeRequest.alreadyRequested.text')),
        okLabel: this.instant(i18nKey('bookings.changeRequest.alreadyRequested.withdraw')),
        cancelLabel: this.instant(i18nKey('bookings.modal.close')),
        onConfirm: () => this.bookingsApi.withdrawChangeRequest(bookingNumber, id),
        errorMessage: this.instant(i18nKey('bookings.changeRequest.withdraw.toast.failure')),
      },
      elementRef,
    ).modalRef.closed;
  }

  private instant(key: string): string {
    return this.translate.instant(key);
  }
}
